; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: test (Test harness (port I/O console)), starts in normal mode
; ============================================================

			org #4000

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs

ntc_start:
			di
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; 9: Cls
			dw kw_cls

			; 10: Print "VB self test 8"
			dw kw_printstrvar, str0
			dw kw_printnl

			; 13: table(0) = AddressOf AddOne
			dw kw_vtov, ap_p_addone_c, arr_table

			; 14: table(1) = AddressOf AddTen
			dw kw_vtov, ap_p_addten_c, arr_table+2

			; 15: table(2) = AddressOf AddArg
			dw kw_vtov, ap_p_addarg_c, arr_table+4

			; 16: total = 0
			dw kw_ztov, var_total

			; 17: CallAddr table(0)
			dw kw_callp, arr_table

			; 18: CallAddr table(1)
			dw kw_callp, arr_table+2

			; 19: Chk total, 11
			dw p_chk_c, var_total, lit_11

			; 20: p = table(2)
			dw kw_vtov, arr_table+4, var_p

			; 21: CallAddr p, 100
			dw kw_ltov, 100, tmp1
			dw kw_callp, var_p, tmp1

			; 22: Chk total, 111
			dw p_chk_c, var_total, lit_111

			; 23: For i = 0 To 1
			dw kw_ztov, var_i
for1_t:

			; 24: CallAddr table(i)
			dw kw_aget, arr_table, var_i, tmp0
			dw kw_callp, tmp0

			; 25: Next
			dw kw_next1l_n, var_i, 1, for1_t
for1_e:

			; 26: Chk total, 122
			dw p_chk_c, var_total, lit_122

			; 27: i = 5
			dw kw_ltov, 5, var_i

			; 28: CallAddr table(2), i * 2
			dw kw_2x, var_i, tmp1
			dw kw_callp, arr_table+4, tmp1

			; 29: Chk total, 132
			dw p_chk_c, var_total, lit_132

			; 30: Register AddressOf AddTen
			dw p_register_c, ap_p_addten_c

			; 31: Chk total, 142
			dw p_chk_c, var_total, lit_142

			; 33: Print
			dw kw_printnl

			; 34: Print t; " tests, "; bad; " failed"
			dw kw_printint, var_t
			dw kw_printstrvar, str1
			dw kw_printint, var_bad
			dw kw_printstrvar, str2
			dw kw_printnl

			; 35: Print "Press a key";
			dw kw_printstrvar, str3

			; 36: Do : Frame : Loop Until Inkey <> 0
do2_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do2_t
do2_e:

			; 37: Print
			dw kw_printnl

			; 38: End
			dw kw_stop

; ============================================================
; sub chk (normal mode)
; ============================================================

p_chk:

			; 41: t = t + 1
			dw kw_inc, var_t

			; 42: Print t; ":";
			dw kw_printint, var_t
			dw kw_printstrvar, str4

			; 43: If got = want Then
			dw kw_cpeqvv, var_chk_got, var_chk_want
			dw kw_goto_iffalse_n, if3_1

			; 44: Print "ok ";
			dw kw_printstrvar, str5

			; 45: Else
			dw if3_e_go
if3_1:

			; 46: Print "FAIL("; got; ") ";
			dw kw_printstrvar, str6
			dw kw_printint, var_chk_got
			dw kw_printstrvar, str7

			; 47: bad = bad + 1
			dw kw_inc, var_bad

			; 48: End If
if3_e:
			dw p_chk_r

; ============================================================
; sub addone (normal mode)
; ============================================================

p_addone:

			; 52: total = total + 1
			dw kw_inc, var_total
			dw p_addone_r

; ============================================================
; sub addten (normal mode)
; ============================================================

p_addten:

			; 56: total = total + 10
			dw kw_addl, var_total, 10, var_total
			dw p_addten_r

; ============================================================
; sub addarg (normal mode)
; ============================================================

p_addarg:

			; 60: total = total + n
			dw kw_add, var_total, var_addarg_n, var_total
			dw p_addarg_r

; ============================================================
; sub register (normal mode)
; ============================================================

p_register:

			; 65: CallAddr entry
			dw kw_callp, var_register_entry
			dw p_register_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if3_e_go:			ld sp, if3_e
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_addone_c:		; call addone (normal)
			ld (p_addone_rs), sp
			ld sp, p_addone
			jp ntc_xn
p_addone_r:		; end of addone
			ld sp, (p_addone_rs)
			jp ntc_xn
p_addten_c:		; call addten (normal)
			ld (p_addten_rs), sp
			ld sp, p_addten
			jp ntc_xn
p_addten_r:		; end of addten
			ld sp, (p_addten_rs)
			jp ntc_xn
p_addarg_c:		; call addarg (normal)
			pop hl			; n
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_addarg_n), de
			ld (p_addarg_rs), sp
			ld sp, p_addarg
			jp ntc_xn
p_addarg_r:		; end of addarg
			ld sp, (p_addarg_rs)
			jp ntc_xn
p_register_c:		; call register (normal)
			pop hl			; entry
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_register_entry), de
			ld (p_register_rs), sp
			ld sp, p_register
			jp ntc_xn
p_register_r:		; end of register
			ld sp, (p_register_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

arr_table:			ds 6		; 3 words
var_total:			dw 0
var_p:			dw 0
var_i:			dw 0
var_t:			dw 0
var_bad:			dw 0
p_chk_rs:			dw 0
var_chk_got:			dw 0
var_chk_want:			dw 0
p_addone_rs:			dw 0
p_addten_rs:			dw 0
p_addarg_rs:			dw 0
var_addarg_n:			dw 0
p_register_rs:			dw 0
var_register_entry:			dw 0
tmp0:			dw 0
tmp1:			dw 0

; numbers passed by address (read only)
ap_p_addone_c:			dw p_addone_c
ap_p_addten_c:			dw p_addten_c
ap_p_addarg_c:			dw p_addarg_c
lit_11:			dw 11
lit_111:			dw 111
lit_122:			dw 122
lit_132:			dw 132
lit_142:			dw 142

; ============================================================
; Strings
; ============================================================

str0:			db "VB self test 8", 0
str1:			db " tests, ", 0
str2:			db " failed", 0
str3:			db "Press a key", 0
str4:			db ":", 0
str5:			db "ok ", 0
str6:			db "FAIL(", 0
str7:			db ") ", 0

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared
; ------------------------------------------------------------
; Scratch space
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread
ntc_ticks:		dw 0			; interrupt count (normal mode, platform handler)
ntc_gnlo:		db 0			; ntc_getn: low byte
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)
ntc_mode:		db 0			; div mode 0=quotient 1=remainder
ntc_sgnq:		db 0			; quotient sign (bit 7)
ntc_sgnr:		db 0			; remainder sign (bit 7)
ntc_lead:		db 0			; printint: digit seen
ntc_icnt:		db 0			; gets: chars typed
ntc_icap:		db 0			; gets: the buffer's capacity
ntc_sptr:		dw 0			; printbuf: text pointer
ntc_iptr:		dw 0			; gets: buffer pointer
ntc_ilink:		dw 0			; gets: where to go when done
ntc_ivar:		dw 0			; inputint / inkey: dest var
ntc_aptr:		dw 0			; atoi: text pointer
ntc_hookon:		db 0			; 1 = the Interrupt hook may run (set, and not running now)
ntc_hookset:	db 0			; 1 = an Interrupt hook is set
ntc_hookpend:	db 0			; 1 = an interrupt came, the hook runs at the next safe point
ntc_hook:		dw 0			; the hook Sub's call stub
ntc_hostix:		dw 0			; host platforms: IX kept over a firmware / BDOS call
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)
				db 40			; ntc_inbuf's capacity (as every string variable has)
ntc_inbuf:		ds 41			; inputint: typed text

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## kw_goto_iffalse (normal mode copy)
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn

;## ntc_for_jump (normal mode copy)
; tails for the FOR / NEXT keywords. DE = var value, HL = limit,
; SP = thread at the label word. Signed compare by flipping bit 15.
; ntc_for_gt: jump to the label if var > limit, else skip it
ntc_for_gt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, carry = var > limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_lt: jump to the label if var < limit, else skip it
ntc_for_lt_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, carry = var < limit
			pop hl
			jp nc, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_le: jump to the label if var <= limit (loop again)
ntc_for_le_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			or a
			sbc hl, de			; limit - var, no carry = var <= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn
; ntc_for_ge: jump to the label if var >= limit (loop again)
ntc_for_ge_n:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
			ex de, hl
			or a
			sbc hl, de			; var - limit, no carry = var >= limit
			pop hl
			jp c, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_next1l (normal mode copy) ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit
kw_next1l_n:
			pop hl
			inc (hl)
			ld e, (hl)
			inc hl
			jr nz, ntc_n1l_nc_n
			inc (hl)
ntc_n1l_nc_n:
			ld d, (hl)
			pop hl
			jp ntc_for_le_n

;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			pop de
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			xor a
			pop hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret

;## kw_inc
;kw_inc, <var>
kw_inc:
			pop hl
			inc (hl)
			ret nz
			inc hl
			inc (hl)
			ret

;## kw_add
;kw_add, <var1>, <var2>, <destvar>
kw_add:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_2x
;kw_2x, <var>, <destvar>
kw_2x:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_cpeqvv ntc_cmp
;kw_cpeqvv, <var1>, <var2>
kw_cpeqvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_cmp_eq

;## kw_cpnevl ntc_cmp
kw_cpnevl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_ne

; ============================================================
; Memory (PEEK / POKE / DEEK / DOKE)
; ============================================================

;## kw_aget
;kw_aget, <arraybase>, <indexvar>, <destvar>
kw_aget:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_callp
;kw_callp, <addressvar>, <arg>, ...  - CallAddr: jump to the procedure call stub whose
;  address (AddressOf) is in the var. SP is then at the arguments, as the stub expects
kw_callp:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp (hl)

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_inkey ntc_data ntc_plat_key
;kw_inkey, <destvar>  - new key press or 0, no wait
kw_inkey:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_inkey_got
			jp ntc_plat_scankey
ntc_inkey_got:
			ld hl, (ntc_ivar)
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_cls ntc_data ntc_plat_screen
;kw_cls
kw_cls:
			ld ix, ntc_next
			jp ntc_plat_cls

;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame flyback
kw_frame:
			ld ix, ntc_next
			jp ntc_plat_frame

;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based)
ntc_cury:		db 0			; cursor row (0 based)
ntc_scols:		db 40			; columns in this mode
ntc_srows:		db 25			; rows
ntc_wrapped:	db 0			; 1 = the last character wrapped to the next line

;## ntc_plat_screen ntc_plat_data ntc_data
; ntc_plat_putc - A = character: out, move on, new line after the last column
ntc_plat_putc:
			out (#fe), a
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr z, ntc_pc_wrap
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_pc_wrap:
			ld a, 1				; wrapped: a new line straight after does nothing
			ld (ntc_wrapped), a
			jr ntc_nl_do

; ntc_plat_newline - column 0, next row (the harness scrolls); nothing straight after a wrap
ntc_plat_newline:
			ld a, (ntc_wrapped)
			or a
			jr z, ntc_nl_do
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_nl_do:
			out (#f9), a
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 25
			jr c, ntc_nl_row
			ld a, 24
ntc_nl_row:
			ld (ntc_cury), a
			jp (ix)

; ntc_plat_backspace - back one and blank that cell
ntc_plat_backspace:
			xor a
			ld (ntc_wrapped), a
			ld a, (ntc_curx)
			or a
			jr nz, ntc_bs_col
			ld a, (ntc_cury)
			or a
			jr z, ntc_bs_none
			dec a
			ld (ntc_cury), a
			ld a, (ntc_scols)
ntc_bs_col:
			dec a
			ld (ntc_curx), a
			out (#f5), a
ntc_bs_none:
			jp (ix)

; ntc_plat_cls - clear, cursor home
ntc_plat_cls:
			out (#fc), a
			xor a
			ld (ntc_wrapped), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			jp (ix)

; ntc_plat_mode - A = mode 0-2 (3 = 2): columns, clear
ntc_plat_mode:
			cp 3
			jr c, ntc_md_ok
			ld a, 2
ntc_md_ok:
			out (#fa), a
			ld b, 20
			or a
			jr z, ntc_md_set
			ld b, 40
			dec a
			jr z, ntc_md_set
			ld b, 80
ntc_md_set:
			ld a, b
			ld (ntc_scols), a
			jr ntc_plat_cls

; ntc_plat_locate - H = column, L = row, 1 based, kept on screen
ntc_plat_locate:
			xor a
			ld (ntc_wrapped), a
			ld a, h
			or a
			jr z, ntc_lc_x0
			dec a
ntc_lc_x0:
			ld c, a
			ld a, (ntc_scols)
			dec a
			cp c
			jr c, ntc_lc_xmax
			ld a, c
ntc_lc_xmax:
			ld (ntc_curx), a
			ld a, l
			or a
			jr z, ntc_lc_y0
			dec a
ntc_lc_y0:
			cp 25
			jr c, ntc_lc_ymax
			ld a, 24
ntc_lc_ymax:
			ld (ntc_cury), a
			ld a, (ntc_curx)
			inc a
			out (#fb), a
			ld a, (ntc_cury)
			inc a
			out (#fb), a
			jp (ix)

;## ntc_plat_key ntc_data
; ntc_plat_scankey - A = key pressed or 0
ntc_plat_scankey:
			in a, (#f8)
			jp (ix)

; ntc_plat_getkey - wait for a key, A = key
ntc_plat_getkey:
			in a, (#fd)
			jp (ix)

;## ntc_plat_frame
ntc_plat_frame:
			jp (ix)

;## ntc_plat_exit ntc_plat_data
ntc_plat_exit:
			jp (ix)


ntc_end:				; the end of the program
